import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene transformation
  if (config.scenePosition) {
    const { x = 0, y = 0, z = 0, rotationXYZ, scaleXYZ } = config.scenePosition;
    group.position.set(x, y, z);

    if (rotationXYZ) {
      group.rotation.set(rotationXYZ[0] || 0, rotationXYZ[1] || 0, rotationXYZ[2] || 0);
    }

    if (scaleXYZ) {
      group.scale.set(scaleXYZ[0] || 1, scaleXYZ[1] || 1, scaleXYZ[2] || 1);
    }
  }

  // Create plane geometry for the card image
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Load texture
  const texture = ctx.textureLoader.load(config.imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // Create basic material (static composition, no lighting)
  const material = new THREE.MeshBasicMaterial({
    map: texture,
    side: THREE.DoubleSide,
    transparent: true,
  });

  // Create and add mesh to group
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Render text label via MSDF font atlas
  if (config.textContent && config.textContent.length > 0) {
    const textMesh = ctx.fontAtlas.createTextMesh(config.textContent[0], {
      fontSize: 0.34,
      color: 0x16161d,
    });

    if (textMesh) {
      textMesh.position.y = 0.3;
      group.add(textMesh);
    }
  }

  // Resource cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (texture) texture.dispose();
    gsap.killTweensOf(group);
  };

  // Event handlers (empty for this static card)
  group.userData.handlers = {};

  return group;
}
